#!/usr/bin/env node
// Writes .github/compat/anchors.txt and paths.txt from a git ref, normally
// `main` at the rework baseline. Run once; afterwards only pull requests that
// add Stubs edit the two lists.
//
//   node .github/scripts/generate-compat-lists.mjs [--ref main] [--root .]
import { execFileSync } from 'node:child_process';
import { mkdirSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { parseArgs } from 'node:util';
import { pageIds } from './lib/markdown.mjs';

const { ref, root: rootArg } = parseArgs({
  options: { ref: { type: 'string', default: 'main' }, root: { type: 'string', default: '.' } },
}).values;
const root = resolve(rootArg);
const git = (...args) => execFileSync('git', args, { cwd: root, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 });

const sha = git('rev-parse', '--short', ref).trim();
const tracked = git('ls-tree', '-r', '--name-only', ref).split('\n').filter(Boolean);

// The pages whose anchors and paths inbound links rely on: README, every docs
// page, and the MCP servers pages. The specialized-agents folder Stub joins
// paths.txt in the pull request that creates it.
const anchorPages = tracked.filter((p) => p === 'README.md' || (p.startsWith('docs/') && p.endsWith('.md')) || p === 'mcp-servers/README.md');
const pagePaths = tracked.filter((p) => (p.startsWith('docs/') && p.endsWith('.md')) || (p.startsWith('mcp-servers/') && p.endsWith('.md')));

const anchors = new Set();
for (const page of anchorPages) {
  for (const id of pageIds(git('show', `${ref}:${page}`))) anchors.add(`${page}#${id}`);
}

const header = (what) => [
  `# ${what} on ${ref} at ${sha}, generated by .github/scripts/generate-compat-lists.mjs.`,
  '# Edit only in pull requests that add Stubs.',
];
mkdirSync(join(root, '.github', 'compat'), { recursive: true });
writeFileSync(join(root, '.github', 'compat', 'anchors.txt'), [...header('The anchors of README.md, the docs/ pages and mcp-servers/README.md'), ...[...anchors].sort()].join('\n') + '\n');
writeFileSync(join(root, '.github', 'compat', 'paths.txt'), [...header('The docs/ and mcp-servers/ page paths'), ...pagePaths.sort()].join('\n') + '\n');
console.log(`anchors.txt: ${anchors.size} ids from ${anchorPages.length} pages; paths.txt: ${pagePaths.length} paths (${ref} at ${sha})`);
